-- pos-vehicle-inventory: Flyway baseline (flattened 2026-09-09 from the previous migration history) with the
-- ADR-0062 tenancy schema folded in. Generated by scripts/db/tenancy/flatten.py from a pg_dump of a
-- database migrated with the retired scripts; the tenancy additions are mechanical and are listed in
-- docs/TENANCY_SCHEMA.md. Global (unscoped) tables: src/main/resources/db/tenancy-global-tables.txt.
--
-- Tenant context: app_current_tenant() reads the session setting app.current_tenant, which the
-- TenantAwareDataSource (pos-tenancy-common, plan WS1) binds per checkout. Until then the owner role
-- carries a transitional default (postgres/init-tenancy.sh) and tests set it per connection.
-- With nothing bound: NULL -> every scoped table reads as empty and refuses inserts (fail closed).

-- Functions are emitted before the tables they reference (pg_dump order); do not validate bodies.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public.app_current_tenant() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$ SELECT NULLIF(current_setting('app.current_tenant', true), '')::uuid $$;

CREATE TABLE public.event_outbox (
    id uuid NOT NULL,
    topic character varying(255) NOT NULL,
    record_key character varying(255) NOT NULL,
    payload text NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    published_at timestamp(6) with time zone,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text
);

CREATE TABLE public.vehicle_care_preferences (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    version bigint NOT NULL,
    created_by_user_id uuid NOT NULL,
    id uuid NOT NULL,
    updated_by_user_id uuid NOT NULL,
    vehicle_id uuid NOT NULL,
    service_notes text,
    preferences jsonb NOT NULL,
    service_interval_months integer,
    CONSTRAINT vehicle_care_preferences_service_interval_months_chk CHECK (((service_interval_months IS NULL) OR ((service_interval_months >= 1) AND (service_interval_months <= 120))))
);

CREATE TABLE public.vehicle_entity (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    model_year integer,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    id uuid NOT NULL,
    vehicle_type character varying(31) NOT NULL,
    make character varying(255),
    model character varying(255),
    vin character varying(255),
    CONSTRAINT vehicle_entity_check CHECK ((((vehicle_type)::text <> 'CAR'::text) OR (model_year IS NOT NULL))),
    CONSTRAINT vehicle_entity_check1 CHECK ((((vehicle_type)::text <> 'COMMERCIAL_TRUCK'::text) OR (model_year IS NOT NULL))),
    CONSTRAINT vehicle_entity_check2 CHECK ((((vehicle_type)::text <> 'PASSENGER_TRUCK'::text) OR (model_year IS NOT NULL))),
    CONSTRAINT vehicle_entity_check3 CHECK ((((vehicle_type)::text <> 'VAN'::text) OR (model_year IS NOT NULL))),
    CONSTRAINT vehicle_entity_vehicle_type_check CHECK (((vehicle_type)::text = ANY (ARRAY[('CAR'::character varying)::text, ('COMMERCIAL_TRUCK'::character varying)::text, ('PASSENGER_TRUCK'::character varying)::text, ('VAN'::character varying)::text])))
);

CREATE TABLE public.vehicle_records (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    is_active boolean NOT NULL,
    model_year integer,
    created_at timestamp(6) with time zone NOT NULL,
    last_service_date timestamp(6) with time zone,
    updated_at timestamp(6) with time zone NOT NULL,
    version bigint NOT NULL,
    account_id uuid NOT NULL,
    vehicle_id uuid NOT NULL,
    vin character varying(17) NOT NULL,
    vin_normalized character varying(17) NOT NULL,
    license_plate character varying(50),
    license_plate_jurisdiction character varying(50),
    description text NOT NULL,
    make character varying(255),
    model character varying(255),
    "trim" character varying(255),
    unit_number character varying(255) NOT NULL,
    odometer jsonb,
    created_by character varying(255),
    updated_by character varying(255)
);

ALTER TABLE ONLY public.event_outbox
    ADD CONSTRAINT event_outbox_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.vehicle_care_preferences
    ADD CONSTRAINT vehicle_care_preferences_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.vehicle_care_preferences
    ADD CONSTRAINT vehicle_care_preferences_tenant_key UNIQUE (tenant_id, id);

ALTER TABLE ONLY public.vehicle_care_preferences
    ADD CONSTRAINT vehicle_care_preferences_vehicle_id_key UNIQUE (tenant_id, vehicle_id);

ALTER TABLE ONLY public.vehicle_entity
    ADD CONSTRAINT vehicle_entity_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.vehicle_entity
    ADD CONSTRAINT vehicle_entity_tenant_key UNIQUE (tenant_id, id);

ALTER TABLE ONLY public.vehicle_records
    ADD CONSTRAINT vehicle_records_pkey PRIMARY KEY (vehicle_id);

ALTER TABLE ONLY public.vehicle_records
    ADD CONSTRAINT vehicle_records_tenant_key UNIQUE (tenant_id, vehicle_id);

ALTER TABLE ONLY public.vehicle_records
    ADD CONSTRAINT vehicle_records_vin_normalized_key UNIQUE (tenant_id, vin_normalized);

CREATE INDEX idx_event_outbox_published_window ON public.event_outbox USING btree (topic, created_at) WHERE (published_at IS NOT NULL);

CREATE INDEX idx_event_outbox_unpublished ON public.event_outbox USING btree (id) WHERE (published_at IS NULL);

CREATE INDEX idx_vcp_vehicle_id ON public.vehicle_care_preferences USING btree (vehicle_id);

CREATE INDEX idx_vr_account_id ON public.vehicle_records USING btree (account_id);

CREATE INDEX idx_vr_license_plate ON public.vehicle_records USING btree (license_plate);

CREATE INDEX idx_vr_unit_number ON public.vehicle_records USING btree (unit_number);

CREATE INDEX idx_vr_vin_normalized ON public.vehicle_records USING btree (vin_normalized);

ALTER TABLE ONLY public.vehicle_care_preferences
    ADD CONSTRAINT fk5iwsw5vk78grnipcu5kkairnk FOREIGN KEY (tenant_id, vehicle_id) REFERENCES public.vehicle_records(tenant_id, vehicle_id);

CREATE INDEX vehicle_care_preferences_tenant_idx ON public.vehicle_care_preferences USING btree (tenant_id);

CREATE INDEX vehicle_entity_tenant_idx ON public.vehicle_entity USING btree (tenant_id);

CREATE INDEX vehicle_records_tenant_idx ON public.vehicle_records USING btree (tenant_id);

ALTER TABLE public.vehicle_care_preferences ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vehicle_care_preferences FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON public.vehicle_care_preferences
    USING (tenant_id = public.app_current_tenant())
    WITH CHECK (tenant_id = public.app_current_tenant());

ALTER TABLE public.vehicle_entity ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vehicle_entity FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON public.vehicle_entity
    USING (tenant_id = public.app_current_tenant())
    WITH CHECK (tenant_id = public.app_current_tenant());

ALTER TABLE public.vehicle_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vehicle_records FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON public.vehicle_records
    USING (tenant_id = public.app_current_tenant())
    WITH CHECK (tenant_id = public.app_current_tenant());
